input.newString:
fn had_reset<S: AsRef<OsStr>>(args: &[S]) -> bool {
    // Indices where "--binary" or "-b", "--tag", and "--untagged" are found
    let binary_index = args
        .iter()
        .position(|x| x.as_ref() == OsStr::new("--binary") || x.as_ref() == OsStr::new("-b"));
    let tag_index = args.iter().position(|x| x.as_ref() == OsStr::new("--tag"));
    let untagged_index = args
        .iter()
        .position(|x| x.as_ref() == OsStr::new("--untagged"));

